from openai import OpenAI

client = OpenAI()
MODEL = "gpt-4.1-mini"          # any chat model
MOD = "omni-moderation-latest"  # or Llama Guard / your own policy classifier
strikes: dict[str, int] = {}    # Redis in production

def flagged(text: str) -> bool:
    return client.moderations.create(model=MOD, input=text).results[0].flagged

def strike(user_id: str, history: list[dict]) -> str:
    strikes[user_id] = strikes.get(user_id, 0) + 1
    queue_for_review(user_id, history)  # humans look at patterns, not single turns
    return REFUSAL

def answer(user_id: str, history: list[dict]) -> str:
    if strikes.get(user_id, 0) >= 3:
        return RATE_LIMITED  # abuse response is code, not a model decision
    # Score the recent conversation: Crescendo looks benign one turn at a time
    recent = "\n".join(m["content"] for m in history[-10:])
    if flagged(recent):
        return strike(user_id, history)
    reply = client.chat.completions.create(model=MODEL, messages=history)
    text = reply.choices[0].message.content
    # Output check catches what disguised inputs (Base64, role-play) slipped past
    if flagged(text):
        return strike(user_id, history + [{"role": "assistant", "content": text}])
    return text
